// Isolated native engine tests. Do not ship this mission-start entry point.
#define Generate_Mission_Starts SAM_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
#include "campaignwaves.h"
#include "campaignbike.h"
#include "campaignrepair.h"
#include <array>
static HouseClass* Enemy(){return HouseClass::As_Pointer(HOUSE_BAD);}
static void Prepare(const std::string& dir){Reset(dir);Enemy()->IsActive=true;Enemy()->IsDefeated=false;PlayerPtr->Credits=1000000;PlayerPtr->Tiberium=0;Enemy()->Credits=1000000;Enemy()->Tiberium=0;Campaign_Waves_Reset();}
static int EnemyCount(){int count=0;for(int i=0;i<Units.Count();++i){auto u=Units.Ptr(i);if(!u->IsInLimbo&&u->House==Enemy()&&u->Strength>0)++count;}for(int i=0;i<Infantry.Count();++i){auto u=Infantry.Ptr(i);if(!u->IsInLimbo&&u->House==Enemy()&&u->Strength>0)++count;}return count;}
static void Barracks(const std::string& dir){Prepare(dir);auto b=new BuildingClass(STRUCT_BARRACKS,HOUSE_GOOD);Check("place player barracks",Put(b,Center()));b->Revealed(PlayerPtr);auto e=new UnitClass(UNIT_LTANK,HOUSE_BAD);Check("place original enemy survivor",Put(e,XY_Cell(Cell_X(Center())+15,Cell_Y(Center()))));e->Assign_Mission(MISSION_SLEEP);e->Commence();Campaign_Enemies_Mark_Extra(e);}
static FactoryClass* Queue(InfantryType kind,HouseClass* owner){auto f=new FactoryClass;Check("queue real infantry production",f->Set(InfantryTypeClass::As_Reference(kind),*owner)&&f->Start());owner->Set_Factory(RTTI_INFANTRYTYPE,f);return f;}
static void Finish(FactoryClass* f){for(int tick=0;tick<50000&&!f->Has_Completed();++tick){++Frame;f->AI();}Check("infantry production genuinely finishes",f->Has_Completed());}
static TARGET Produce(InfantryType kind){auto f=Queue(kind,PlayerPtr);Finish(f);auto id=f->Get_Object()->As_Target();Check("sidebar successfully releases infantry",PlayerPtr->Place_Object(RTTI_INFANTRYTYPE,-1));return id;}
static std::array<std::int32_t,8> WaveState(const std::string& dir){CCFileClass f((dir+"/wave-state.bin").c_str());Check("open wave state",f.Open(WRITE));Check("write versioned wave state",Campaign_Waves_Save(f));f.Close();std::ifstream in(dir+"/wave-state.bin",std::ios::binary);char h[8];std::array<std::int32_t,8> result{};in.read(h,8);Check("wave footer is version two",!std::memcmp(h,"CNCWAV02",8));in.read(reinterpret_cast<char*>(result.data()),sizeof(result));return result;}
static void Toggle(const std::string& dir){Barracks(dir);Check("waves default off for existing campaigns",!Campaign_Waves_Enabled());int baseline=EnemyCount();for(int i=0;i<12;++i){Frame+=5*60*TICKS_PER_SECOND;Campaign_Waves_AI();}Check("off mode never creates timed reinforcements",EnemyCount()==baseline);Produce(INFANTRY_E1);Check("ordinary rifleman does not toggle waves",!Campaign_Waves_Enabled());auto f=Queue(INFANTRY_E2,PlayerPtr);Finish(f);Check("finished but not released grenadier does not toggle",!Campaign_Waves_Enabled());PlayerPtr->Abandon_Production(RTTI_INFANTRYTYPE);Check("cancelled grenadier does not toggle",!Campaign_Waves_Enabled());int money=PlayerPtr->Available_Money();Produce(INFANTRY_E2);Check("first actually released grenadier enables waves",Campaign_Waves_Enabled());Check("grenadier retains original cash reward and unlimited power",PlayerPtr->Available_Money()>money&&PlayerPtr->Power>=1000000);PlayerPtr->Place_Object(RTTI_INFANTRYTYPE,-1);Check("duplicate placement cannot toggle twice",Campaign_Waves_Enabled());Campaign_Waves_AI();Check("enabled mode immediately delivers the old first wave of six",EnemyCount()==baseline+6);Campaign_Enemies_Apply();Check("wave troops are never multiplied by production quota",EnemyCount()==baseline+6);
 Check("save enabled reinforcements",Save_Game((dir+"/on.sav").c_str(),"GRENADIER WAVES ON"));Check("reload enabled reinforcements",Load_Game((dir+"/on.sav").c_str()));Check("enabled toggle survives save/load",Campaign_Waves_Enabled());baseline=EnemyCount();Campaign_Waves_AI();Check("reload does not deliver an extra free wave",EnemyCount()==baseline);Produce(INFANTRY_E2);Check("second grenadier disables future reinforcements",!Campaign_Waves_Enabled());baseline=EnemyCount();for(int i=0;i<20;++i){Frame+=60*TICKS_PER_SECOND;Campaign_Waves_AI();}Check("disabling stops spawning and keeps arrived troops",EnemyCount()==baseline);Check("save off reinforcements",Save_Game((dir+"/off.sav").c_str(),"GRENADIER WAVES OFF"));Check("reload off reinforcements",Load_Game((dir+"/off.sav").c_str()));Check("disabled toggle survives save/load",!Campaign_Waves_Enabled());Produce(INFANTRY_E2);Campaign_Waves_AI();Check("third grenadier resumes with the next larger wave of nine",Campaign_Waves_Enabled()&&EnemyCount()==baseline+9);
 auto state=WaveState(dir);for(int i=0;i<3;++i){Frame=state[1];Campaign_Waves_AI();state=WaveState(dir);while(state[3]&&state[3]<13){++Frame;Campaign_Waves_AI();state=WaveState(dir);if(state[3])break;}}
 // Explicitly schedule a large in-progress wave through normal progression.
 Frame=state[1];Campaign_Waves_AI();state=WaveState(dir);Check("later waves grow and deliver in bounded chunks",state[2]>=5&&state[3]>0&&state[4]<=12);Check("save a partially delivered wave",Save_Game((dir+"/partial-wave.sav").c_str(),"PARTIAL WAVE"));Check("reload a partially delivered wave",Load_Game((dir+"/partial-wave.sav").c_str()));auto loaded=WaveState(dir);Check("pending wave quota survives save/load",loaded==state);Produce(INFANTRY_E2);state=WaveState(dir);Check("turning off cancels only the undelivered quota",!state[0]&&state[3]==0&&state[4]==0);baseline=EnemyCount();Frame+=600*TICKS_PER_SECOND;Campaign_Waves_AI();Check("cancelled pending wave never resumes",EnemyCount()==baseline);
}
static void Filters(const std::string& dir){Barracks(dir);auto enemyBarracks=new BuildingClass(STRUCT_HAND,HOUSE_BAD);Put(enemyBarracks,XY_Cell(Cell_X(Center())-8,Cell_Y(Center())));auto f=Queue(INFANTRY_E2,Enemy());Finish(f);Check("enemy grenadier actually releases",enemyBarracks->Exit_Object(f->Get_Object())==2);f->Completed();Enemy()->Set_Factory(RTTI_INFANTRYTYPE,nullptr);delete f;Check("enemy grenadier never changes player toggle",!Campaign_Waves_Enabled());GameToPlay=GAME_SKIRMISH;Produce(INFANTRY_E2);Check("skirmish grenadiers do not enable campaign waves",!Campaign_Waves_Enabled());GameToPlay=GAME_NORMAL;
 Barracks(dir);Special.IsJurassic=true;Produce(INFANTRY_E2);int before=Units.Count();Campaign_Waves_AI();int dinosaurs=0;for(int i=0;i<Units.Count();++i){auto u=Units.Ptr(i);if(!u->IsInLimbo&&u->House==Enemy()&&u->Class->Type>=UNIT_TRIC&&u->Class->Type<=UNIT_STEG)++dinosaurs;}Check("bonus dinosaur missions receive dinosaur reinforcements",Units.Count()>=before+6&&dinosaurs>=6);Special.IsJurassic=false;
}
static void BikeHealth(const std::string& dir){Prepare(dir);auto bike=new UnitClass(UNIT_BIKE,HOUSE_GOOD);int stock=bike->Class->MaxStrength;Check("new player bike has twice original maximum and current HP",bike->Strength==2*stock&&Campaign_Max_Health(bike)==2*stock);Check("place boosted player bike",Put(bike,Center()));bike->Strength=stock;Check("damaged boosted bike has correct half health ratio",bike->Health_Ratio()==0x80);auto id=bike->As_Target();Check("save half-health boosted bike",Save_Game((dir+"/bike.sav").c_str(),"DOUBLE BIKE HP"));for(int repeat=0;repeat<3;++repeat){Check("reload boosted bike",Load_Game((dir+"/bike.sav").c_str()));bike=As_Unit(id);Check("repeated load preserves boosted damage without multiplying HP",bike&&bike->Strength==stock&&bike->Health_Ratio()==0x80);}
 bike->House=Enemy();Campaign_Bike_Health_Apply(bike);Check("losing player ownership scales bike back proportionally",bike->Strength==(stock+1)/2&&Campaign_Max_Health(bike)==stock);bike->House=PlayerPtr;Campaign_Bike_Health_Apply(bike);Check("regaining ownership restores proportional boosted cap",bike->Strength==2*((stock+1)/2)&&Campaign_Max_Health(bike)==2*stock);bike->Strength=0;Campaign_Bike_Health_Apply(bike);Check("health migration never resurrects a dead bike",bike->Strength==0);delete bike;bike=new UnitClass(UNIT_BIKE,HOUSE_GOOD);Check("reused unit slots receive exactly one health boost",bike->Strength==2*stock);auto enemyBike=new UnitClass(UNIT_BIKE,HOUSE_BAD);Check("enemy bike HP remains unchanged",enemyBike->Strength==stock&&Campaign_Max_Health(enemyBike)==stock);
}
static void Legacy(const std::string& dir){Barracks(dir);auto bike=new UnitClass(UNIT_BIKE,HOUSE_GOOD);Put(bike,XY_Cell(Cell_X(Center())-5,Cell_Y(Center())));int stock=bike->Class->MaxStrength;bike->Strength=stock/2;auto id=bike->As_Target();Produce(INFANTRY_E2);Campaign_Waves_AI();Check("save compatibility source",Save_Game((dir+"/old-format.sav").c_str(),"LEGACY WAVE AND BIKE"));std::ifstream in(dir+"/old-format.sav",std::ios::binary);std::string bytes((std::istreambuf_iterator<char>(in)),{});auto w=bytes.rfind("CNCWAV02"),b=bytes.rfind("CNCBIK02");Check("find both new versioned footers",w!=std::string::npos&&b!=std::string::npos);if(w==std::string::npos||b==std::string::npos)return;std::uint32_t count;std::memcpy(&count,&bytes[b+8],4);bytes[b+7]='1';bytes.erase(b+12+8*count,UNIT_MAX);bytes[w+7]='1';bytes.erase(w+8,4);{std::ofstream out(dir+"/old-format.sav",std::ios::binary|std::ios::trunc);out.write(bytes.data(),bytes.size());}Check("load old wave and bike formats",Load_Game((dir+"/old-format.sav").c_str()));bike=As_Unit(id);Check("old automatic wave state stays disabled until grenadier production",!Campaign_Waves_Enabled());Check("old damaged bike gains doubled cap proportionally",bike&&bike->Strength==stock&&bike->Health_Ratio()==0x80);}
static void MobileRepair(const std::string& dir,int kind){Prepare(dir);TechnoClass* object=kind==0?static_cast<TechnoClass*>(new UnitClass(UNIT_BIKE,HOUSE_GOOD)):kind==1?static_cast<TechnoClass*>(new UnitClass(UNIT_MTANK,HOUSE_GOOD)):kind==2?static_cast<TechnoClass*>(new InfantryClass(INFANTRY_E1,HOUSE_GOOD)):static_cast<TechnoClass*>(new AircraftClass(AIRCRAFT_ORCA,HOUSE_GOOD));if(kind==3){static_cast<AircraftClass*>(object)->Altitude=AircraftClass::FLIGHT_LEVEL;for(int cell=0;cell<MAP_CELL_TOTAL;++cell)if(Map.In_Radar(cell))Map.Map_Cell(cell,PlayerPtr,true);}Check("place auto-repair mobile object",Put(object,Center()));object->Assign_Mission(MISSION_SLEEP);object->Commence();int maximum=Campaign_Max_Health(object);object->Strength=maximum-1;int money=PlayerPtr->Available_Money();Frame=14;object->TechnoClass::AI();Check("repair waits until one-second tick",object->Strength==maximum-1&&PlayerPtr->Available_Money()==money);Frame=15;object->TechnoClass::AI();Check("native shared AI heals mobile object without exceeding cap",object->Strength==maximum&&PlayerPtr->Available_Money()==money);money=PlayerPtr->Available_Money();Frame=30;object->TechnoClass::AI();Check("full mobile objects do not consume repair funds",PlayerPtr->Available_Money()==money);object->Strength=maximum-10;PlayerPtr->Credits=0;PlayerPtr->Tiberium=0;Frame=45;object->TechnoClass::AI();Check("empty wallet allows automatic mobile regeneration",object->Strength>maximum-10);PlayerPtr->Credits=100000;Frame=60;object->TechnoClass::AI();Check("mobile healing resumes automatically with funds",object->Strength>maximum-10);object->Strength=maximum-10;object->Limbo();Frame=75;object->TechnoClass::AI();Check("transport/limbo objects are not healed",object->Strength==maximum-10);Check("place object again",Put(object,Center()));GameToPlay=GAME_SKIRMISH;if(kind==0)Campaign_Bike_Health_Apply(static_cast<UnitClass*>(object));int hp=object->Strength;Frame=90;object->TechnoClass::AI();Check("skirmish receives no custom auto healing",object->Strength==hp);GameToPlay=GAME_NORMAL;object->House=Enemy();if(kind==0)Campaign_Bike_Health_Apply(static_cast<UnitClass*>(object));hp=object->Strength;Frame=105;object->TechnoClass::AI();Check("enemy mobile objects receive no player auto healing",object->Strength==hp);object->House=PlayerPtr;object->Strength=0;Frame=120;object->TechnoClass::AI();Check("dead mobile objects are never resurrected by auto healing",object->Strength==0);}
static void BuildingRepair(const std::string& dir,StructType type){Prepare(dir);auto b=new BuildingClass(type,HOUSE_GOOD);Check("place auto-repair building",Put(b,Center()));b->Assign_Mission(MISSION_GUARD);b->Commence();int maximum=Campaign_Max_Health(b),money=PlayerPtr->Available_Money();b->Strength=maximum-1;b->IsRepairing=false;Frame=15;b->AI();Check("native building AI automatically repairs to its effective cap",b->Strength==maximum&&PlayerPtr->Available_Money()==money-b->Class->Repair_Cost());money=PlayerPtr->Available_Money();Frame=30;b->AI();Check("full buildings stop spending",PlayerPtr->Available_Money()==money);b->Strength=maximum-10;b->Assign_Mission(MISSION_CONSTRUCTION);b->Commence();b->IsRepairing=false;Frame=45;b->AI();Check("construction phase does not start auto repair",!b->IsRepairing);}
static void Walls(const std::string& dir){Prepare(dir);CELL cell=Center();Map[cell].Overlay=OVERLAY_BRICK_WALL;Map[cell].Owner=HOUSE_GOOD;Map[cell].OverlayData=16+5;int money=PlayerPtr->Available_Money();Frame=15;Campaign_Auto_Repair_Walls();Check("owned concrete wall repairs one damage stage without changing connections",Map[cell].OverlayData==5&&PlayerPtr->Available_Money()<money);money=PlayerPtr->Available_Money();Frame=30;Campaign_Auto_Repair_Walls();Check("undamaged concrete walls cost nothing",PlayerPtr->Available_Money()==money);Map[cell].OverlayData=16+5;Map[cell].Owner=HOUSE_BAD;Frame=45;Campaign_Auto_Repair_Walls();Check("enemy concrete walls do not receive player repair",Map[cell].OverlayData==21);Map[cell].Overlay=OVERLAY_NONE;Map[cell].Owner=HOUSE_GOOD;Frame=60;Campaign_Auto_Repair_Walls();Check("destroyed walls are not recreated",Map[cell].Overlay==OVERLAY_NONE);}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);Toggle(dir);Filters(dir);BikeHealth(dir);Legacy(dir);for(int kind=0;kind<4;++kind)MobileRepair(dir,kind);for(auto type:{STRUCT_OBELISK,STRUCT_ATOWER,STRUCT_SAM,STRUCT_POWER,STRUCT_CONST})BuildingRepair(dir,type);Walls(dir);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
